if($json.error||$json.done!==true||$json.done_reason!=='stop'||typeof $json.message?.content!=='string'||!$json.message.content.trim())return fail('model-unavailable');
let value;try{value=JSON.parse($json.message.content);}catch{return fail('invalid-result');}
if(!value||Object.keys(value).join(',')!=='points'||!Array.isArray(value.points)||(value.points.length<2||value.points.length>3)||value.points.some(p=>typeof p!=='string'||!p.trim()||! /\p{Script=Thai}/u.test(p)||/[\r\n<>]|https?:\/\/|^\s*[-*#•]/i.test(p)))return fail('invalid-result');
const summary=value.points.map(p=>p.trim()).join('\n');
const count=[...new Intl.Segmenter('th',{granularity:'grapheme'}).segment(summary)].length;
const banned=[/(?:รับประกัน|การันตี|รับรอง)(?:ผลตอบแทน|กำไร|อนุมัติ|เคลมผ่าน|ความคุ้มครอง)/u,/(?:ไม่ขาดทุน|ไม่มีความเสี่ยง|ผลตอบแทนแน่นอน|อนุมัติแน่นอน|เคลมผ่านแน่นอน|คุ้มครองทุกกรณี|จ่ายแน่นอน)/u];
const identifiers=[/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i,/(?:^|\D)0\d(?:[-\s]?\d){8,9}(?:\D|$)/,/(?:^|\D)\d(?:[-\s]?\d){12}(?:\D|$)/];
if(count<60||count>300||banned.some(pattern=>pattern.test(summary))||identifiers.some(pattern=>pattern.test(summary)))return fail('invalid-result');
const numbers=summary.match(/\p{N}+(?:[.,]\p{N}+)*/gu)||[];
const sourceNumbers=new Set(prep.source.match(/\p{N}+(?:[.,]\p{N}+)*/gu)||[]);
if(numbers.some(number=>!sourceNumbers.has(number)))return fail('invalid-result');
return [{json:{status:'generated',summary,requestId:prep.requestId,instructionHash:prep.instructionHash,editorialInstructionVersion:prep.editorialInstructionVersion,sourceRevision:prep.sourceRevision,promptVersion:prep.promptVersion}}];

const prep=$('เตรียมสรุปบทความ').item.json;
const fail=()=>[{json:{error:'model-unavailable'}}];
if(!prep.valid||prep.provider!=='openai'||prep.inputTokenUpperBound>200000||prep.maxCostUsd!==0.03)return fail();
if($json.error||$json.status!=='completed'||$json.store!==false||$json.service_tier!=='default'||$json.incomplete_details)return fail();
const content=Array.isArray($json.output)?$json.output.flatMap(item=>Array.isArray(item.content)?item.content:[]):[];
if(content.some(part=>part.type==='refusal'||part.refusal))return fail();
const text=content.filter(part=>part.type==='output_text'&&typeof part.text==='string').map(part=>part.text).join('')||(typeof $json.output_text==='string'?$json.output_text:'');
if(!text.trim())return fail();
return [{json:{done:true,done_reason:'stop',message:{content:text}}}];
